draw:
var omega = Math.sqrt(p.k / p.mass);
var A = p.amplitude;
var x = A * Math.cos(omega * t);
var v = -A * omega * Math.sin(omega * t);
var E = 0.5 * p.k * A * A;
var U = 0.5 * p.k * x * x;
var K = E - U;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1.5;

var cx = W * 0.36, baseY = H * 0.84, top = H * 0.14;
var xs = (W * 0.30) / A;
var ys = (baseY - top) / E;

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(cx - W * 0.32, baseY); ctx.lineTo(cx + W * 0.32, baseY); ctx.stroke();
ctx.beginPath(); ctx.moveTo(cx, baseY + 6); ctx.lineTo(cx, top - 6); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("x", cx + W * 0.30, baseY + 16);
ctx.fillText("energy", cx + 6, top - 10);

ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
var i;
for (i = 0; i <= 80; i++) {
  var xx = -A * 1.05 + (2.1 * A) * i / 80;
  var px = cx + xx * xs;
  var py = baseY - 0.5 * p.k * xx * xx * ys;
  if (i === 0) { ctx.moveTo(px, py); } else { ctx.lineTo(px, py); }
}
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("U = kx^2 / 2", cx + A * 1.0 * xs - 60, baseY - E * ys - 10);

var eY = baseY - E * ys;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
ctx.setLineDash([4, 4]);
ctx.beginPath(); ctx.moveTo(cx - A * xs, eY); ctx.lineTo(cx + A * xs, eY); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.accent;
ctx.fillText("total E", cx - A * xs - 4, eY - 8);

var bx = cx + x * xs;
var by = baseY - U * ys;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 3;
ctx.beginPath(); ctx.moveTo(bx, by); ctx.lineTo(bx, eY); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(bx, by, 5, 0, 6.2832); ctx.fill();
ctx.fillStyle = C.accent;
ctx.fillText("K", bx + 6, (by + eY) / 2 + 4);

ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.setLineDash([2, 4]);
ctx.beginPath(); ctx.moveTo(bx, by); ctx.lineTo(bx, baseY); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.figure;
ctx.fillText("U", bx + 6, (by + baseY) / 2 + 4);

var barX = W * 0.80, barW = W * 0.10, barTop = top, barBot = baseY;
var full = barBot - barTop;
ctx.strokeStyle = C.rule;
ctx.strokeRect(barX, barTop, barW, full);
var hK = full * (K / E);
ctx.fillStyle = C.accent;
ctx.fillRect(barX, barBot - hK, barW, hK);
ctx.fillStyle = C.figure;
ctx.fillRect(barX, barTop, barW, full - hK);
ctx.fillStyle = C.faint;
ctx.fillText("K", barX + barW + 6, barBot - hK / 2);
ctx.fillText("U", barX + barW + 6, barTop + (full - hK) / 2);

out.note = "x = " + x.toFixed(3) + " m, v = " + Math.abs(v).toFixed(2) + " m/s, K = " + K.toFixed(3) + " J, U = " + U.toFixed(3) + " J, total = " + E.toFixed(3) + " J";
